#!/usr/bin/env bash
# Copies the current kitty colors (generated by DMS) into the WezTerm config used on Windows/WSL.
# Re-run after changing the wallpaper, then: dot commit -am "update wezterm colors" && dot push
set -euo pipefail

KITTY="$HOME/.config/kitty"
WEZ="$HOME/.config/wezterm/wezterm.lua"

block=$(awk '
  NF >= 2 && $1 !~ /^#/ { c[$1] = $2 }
  END {
    q = "\047"
    printf "config.colors = {\n"
    printf "  foreground = %s%s%s,\n", q, c["foreground"], q
    printf "  background = %s%s%s,\n", q, c["background"], q
    printf "  cursor_bg = %s%s%s,\n", q, c["cursor"], q
    printf "  cursor_border = %s%s%s,\n", q, c["cursor"], q
    printf "  cursor_fg = %s%s%s,\n", q, c["cursor_text_color"], q
    printf "  selection_fg = %s%s%s,\n", q, c["selection_foreground"], q
    printf "  selection_bg = %s%s%s,\n", q, c["selection_background"], q
    printf "  ansi = {"; for (i = 0; i < 8; i++) printf " %s%s%s,", q, c["color" i], q; printf " },\n"
    printf "  brights = {"; for (i = 8; i < 16; i++) printf " %s%s%s,", q, c["color" i], q; printf " },\n"
    printf "  tab_bar = {\n"
    printf "    background = %s%s%s,\n", q, c["tab_bar_background"], q
    printf "    active_tab = { bg_color = %s%s%s, fg_color = %s%s%s, intensity = %sBold%s },\n", q, c["active_tab_background"], q, q, c["active_tab_foreground"], q, q, q
    printf "    inactive_tab = { bg_color = %s%s%s, fg_color = %s%s%s },\n", q, c["inactive_tab_background"], q, q, c["inactive_tab_foreground"], q
    printf "    new_tab = { bg_color = %s%s%s, fg_color = %s%s%s },\n", q, c["tab_bar_background"], q, q, c["inactive_tab_foreground"], q
    printf "  },\n}"
  }' "$KITTY/dank-theme.conf" "$KITTY/dank-tabs.conf")

# Replace everything between the BEGIN/END markers
awk -v block="$block" '
  /^-- BEGIN kitty colors/ { print; print block; skip = 1; next }
  /^-- END kitty colors/ { skip = 0 }
  !skip
' "$WEZ" > "$WEZ.tmp" && mv "$WEZ.tmp" "$WEZ"
echo "Updated colors in $WEZ"
